# [LATER-STEP] meeting_summary.py\n# Summarize live meeting transcript chunks using IBM watsonx.ai generative AI.\n# The summarizer consumes caption chunks produced by the same-scenario pipeline\n# (e.g., partial_results.py) and produces a running summary and a final summary.\n\nimport asyncio\nimport json\nimport os\nimport sys\nfrom ibm_watson import WatsonNaturalLanguageGenerationV1\nfrom ibm_cloud_sdk_core.authenticators import IAMAuthenticator\n\n# ----------------------------------------------------------\n# Environment config (watsonx.ai)\n# ----------------------------------------------------------\nAPIKEY = os.getenv('WATSONX_APIKEY')\nURL = os.getenv('WATSONX_URL', 'https://api.us-south.natural-language-generation.watson.cloud.ibm.com')\nif not APIKEY:\n    print('Set WATSONX_APIKEY environment variable')\n    sys.exit(1)\nauthenticator = IAMAuthenticator(APIKEY)\ngeneration = WatsonNaturalLanguageGenerationV1(\n    version='2024-03-28',\n    authenticator=authenticator,\n)\ngeneration.set_service_url(URL)\n\n# ----------------------------------------------------------\n# Helper: generate a summary for a collection of sentences\n# ----------------------------------------------------------\nasync def summarize(text: str) -> str:\n    \"\"\"Call watsonx.ai to produce a concise summary of `text`.\n\n    Returns the generated summary.\n    \"\"\"\n    try:\n        response = generation.summarize(\n            text=text,\n            model_id='ibm/granite-13b-instruct-v2',\n            temperature=0.2,\n            max_new_tokens=150,\n        ).get_result()\n        summary = response.get('summary', '')\n        return summary\n    except Exception as e:\n        print('Summarization error:', e)\n        return ''\n\n# ----------------------------------------------------------\n# Live caption source (placeholder)\n# ----------------------------------------------------------\n# In the full system this would be replaced by the stream from\n# partial_results.py or a WebSocket listener.\n# ----------------------------------------------------------\nasync def caption_generator():\n    # Dummy live chunks (in practice replace with real async source)\n    chunks = [\n        {'transcript': 'Welcome everyone to the monthly engineering sync.', 'final': False},\n        {'transcript': 'We reviewed the roadmap for Q4 and adjusted timelines.', 'final': False},\n        {'transcript': 'Action items include updating the backlog and preparing demo assets.', 'final': True},\n    ]\n    for c in chunks:\n        yield c\n\n# ----------------------------------------------------------\n# Running summary state\n# ----------------------------------------------------------\nrunning_summary = ''\n\nasync def main():\n    global running_summary\n    async for chunk in caption_generator():\n        txt = chunk['transcript']\n        print('--- New caption chunk ---')\n        print(txt)\n        # Append to running text\n        running_summary += txt + ' ' \n        # Generate incremental summary (optional)\n        inc_summary = await summarize(running_summary)\n        print('Incremental summary:', inc_summary)\n    # Final summary after the meeting ends\n    final_summary = await summarize(running_summary)\n    print('--- Final meeting summary ---')\n    print(final_summary)\n\nif __name__ == '__main__':\n    asyncio.run(main())\n